/**
 * Bundles the Iconify icons referenced by the landing theme. This prevents
 * @iconify/vue from falling back to api.iconify.design at runtime.
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const source = JSON.parse(
  readFileSync(resolve(root, 'node_modules/@iconify-json/fa6-solid/icons.json'), 'utf8')
)
const names = [
  'bolt', 'check', 'chevron-left', 'chevron-right', 'copy', 'cubes',
  'envelope', 'file-code', 'language', 'magnifying-glass', 'minus',
  'mobile-screen', 'paintbrush', 'palette', 'pause', 'play', 'robot', 'rocket',
  'shapes', 'star', 'universal-access', 'xmark',
]
const collection = {
  prefix: source.prefix,
  icons: Object.fromEntries(names.map((name) => [name, source.icons[name]])),
  width: source.width,
  height: source.height,
}

mkdirSync(resolve(root, 'src/generated'), { recursive: true })
writeFileSync(
  resolve(root, 'src/generated/icons-bundle.ts'),
  `// AUTO-GENERATED by scripts/generate-icon-bundle.mjs — do not edit manually.\n` +
    `import type { IconifyJSON } from '@iconify/vue'\n\n` +
    `const collections: IconifyJSON[] = ${JSON.stringify([collection], null, 2)}\n\n` +
    `export default collections\n`
)
